import sys,re,random,json
sys.path.insert(0,sys.argv[1]); from common import *
exec(open(sys.argv[1]+'/kparse.py').read())
A,B=int(sys.argv[2]),int(sys.argv[3]); WRITE=len(sys.argv)>4
SRC="Kubiak, P.J. (2009) Fire responses of bushland plants after the January 1994 wildfires in northern Sydney. Cunninghamia 11(1): 131–165."
