MAP={'R':'resprouter','pR':'resprouter','?R':'resprouter','K':'obligate','pK':'obligate','?K':'obligate'}
ANN=[(r'–?\(shd\)','shedding seed or spores'),(r'–?\(?gre?e?n\)?\.?','green fruit'),(r'–ri\.?','ripe fruit'),(r'\(ripe\)','ripe fruit'),(r'–?\(?imm\)?','immature fruit'),(r'–?\(?buds\)?','flowers in bud'),(r'\s*–?\s*\(1\)','one plant'),(r'–\(?adv\)?','advanced seedlings'),(r'–\s?a few fruit','a few fruit'),(r'–a small pop\.','a small population'),(r'–m\.i\.f\.','after moderate intensity fire')]
def strip_u(s): return re.sub(r'</?u>','',s)
def parse(cell):
    """first value of a cell -> dict(lo,hi,plus,unit,approx,unc,ann,extra,bold,raw)"""
    s=strip_u(cell).strip(); raw=s
    if s=='At least 5 years': return dict(lo='5',hi=None,plus='atleast',unit='y',approx=False,unc=False,ann=[],extra='',bold=False,raw=raw)
    if s=='Less than 1 year': return dict(lo='1',hi=None,plus='less',unit='y',approx=False,unc=False,ann=[],extra='',bold=False,raw=raw)
    m=re.match(r'^(\*\*)?(\?)?(c\.\s?)?(\?)?(\d+(?:\.\d+)?)(?:\s*–\s*(\d+(?:\.\d+)?))?(\+)?\s*([wy])?(\?)?',s)
    if not m: return None
    rest=s[m.end():]
    unit=m.group(8)
    extra=''
    sp=re.split(r',\s*|(?=\*\*)',rest,maxsplit=1)
    head=sp[0]; extra=sp[1] if len(sp)>1 else ''
    if not unit:
