    ann=[]
    for pat,lab in ANN:
        if re.search(pat,head): ann.append(lab); head=re.sub(pat,'',head)
    head=head.replace('**','').strip(' .')
    assert head=='' , (cell,head)
    return dict(lo=m.group(5),hi=m.group(6),plus='plus' if m.group(7) else '',unit=unit,approx=bool(m.group(3)),unc=bool(m.group(2) or m.group(4) or m.group(9)),ann=ann,extra=extra.replace('**','').strip(),bold=bool(m.group(1)),raw=raw)
def r3(x):
    v=round(float(x)/52,3); return ('%.3f'%v).rstrip('0').rstrip('.')
def fmt(p,years):
    """years=True: convert to years; else keep paper unit"""
    conv=years and p['unit']=='w'
    f=(lambda x:r3(x)) if conv else (lambda x:x)
    v=f(p['lo'])+('-'+f(p['hi']) if p['hi'] else '')
    if p['plus'] in ('plus',): v='>'+v
    if p['plus']=='atleast': v='>='+v
    if p['plus']=='less': v='<'+v
    return v,conv
UN={'w':'weeks','y':'years'}
def fill(d,notes,col,cell,label,fixed):
    p=parse(cell)
    assert p and p['unit'],(col,cell)
    v,conv=fmt(p,fixed)
    d[col]=v
    n=[f"{label} printed '{p['raw']}'"]
    if conv: n.append(f"{col} converted from {p['lo']+('-'+p['hi'] if p['hi'] else '')} weeks")
    if p['approx']: n.append("c. = approximately")
    if p['unc']: n.append("'?' printed: uncertain value")
    if p['plus']=='plus': n.append("'+' printed after value: that time or more")
    if p['plus']=='atleast': n.append("printed 'At least 5 years'")
    if p['ann']: n.append("annotation: "+', '.join(p['ann']))
    if p['bold']: n.append("bold = sizable proportion of population flowering")
    if p['extra']: n.append(f"later value(s) printed: {p['extra']} (bold = sizable proportion of population flowering)")
    notes.append('; '.join(n))
    if not fixed: d["Time_unit"]=UN[p['unit']]
def base(c):
