    intro=name.startswith('*'); name=name.lstrip('*')
    if name.startswith('(*?)'): name=name[4:]; n.append("printed '(*?)' before name: possibly exotic; not marked as introduced")
    for q in ('(s.lat.)','(s.str.)'):
        if q in name: name=name.replace(q,'').strip(); n.append(f"name printed with {q}")
    if '(syn.' in name: syn=re.search(r'\((syn\.[^)]*)\)',name).group(1); name=re.sub(r'\s*\(syn\.[^)]*\)','',name); n.append(f"printed {syn}")
    pt=name.split(); g=pt[0]; rest=pt[1:]; sub=''
    for k in ('subsp.','var.'):
        if k in rest: i=rest.index(k); sub=' '.join(rest[i:]); rest=rest[:i]
    s=' '.join(rest)
    if intro: sub=(sub+' *').strip()
    if intro: n.append("* = exotic species")
    d=dict(Genus=g,Species=s,subsp=sub,scientific_name=sci(g,s,intro),Family=fam,Fire_type="wildfire",Fire_season_categorical="Summer",Fire_severity_categorical="High",Source=SRC,File_name=F)
    return d,n
FIRE="fires of 6-8 January 1994 (season derived from date), generally of apparently high or very high intensity; responses are for plants with 100% leaf scorch"
LCRX=dict(Latitude=-33.75,Longitude=151.0833)
rows=[]
for p,c in ROWS:
    if not (A<=p<=B): continue
    lcr,nl=c[3].strip(),c[4].strip().replace(' ','')
    extra_site=[]
    if lcr.startswith('R(1)m.i.f'): extra_site.append("LCR: one plant resprouted after low to medium intensity fire; canopy of its host not 100% scorched (printed 'R(1)m.i.f')"); lcr='R'
    if nl.startswith('Thehost'): extra_site.append("NL column: the host of this mistletoe was also killed by the same fire"); nl=''
    if nl.startswith('K;r–m.i.f'): extra_site.append("NL cell printed 'K;r–m.i.f71w': K = majority killed, r = small proportion resprouted, m.i.f = moderate intensity fire, 71w meaning not stated"); nl='K;r'
    page=f"Appendix 1 p. {p+130}"
    data=[]; dcols={}
    def addnote(x): data.append(x)
    # free-text cells
    seed,flr,fls,frr,frs,pjp,sjp=c[5],c[6],c[7],c[8],c[9],c[10],c[11]
    if seed:
        if re.match(r'^\??\d',seed): addnote(f"seedlings first observed: {seed} after fire (adv = advanced seedlings; (1) = one plant; ? = uncertain)")
        else: addnote(f"seedlings column: {seed}")
    d0={}
    if flr and not re.match(r'^[<\d?c*]',strip_u(flr)): addnote(f"First flowering Resp column: {flr}"); flr=''
    if frr and frr.startswith('Note'): addnote(f"First fruiting Resp column: {frr}"); frr=''
    under = flr.startswith('<u>') and flr==fls
    if under:
        addnote(f"first flowering {strip_u(flr)} after fire printed underlined across Resp and Seed columns: unclear whether plants grew from seed or resprouted; not assigned to a column"); flr=fls=''
    if frr.startswith('<u>') and frr==frs:
        addnote(f"first fruiting {strip_u(frr)} after fire, unclear whether from seed or resprouts (underlined)"); frr=frs=''
    if frr: addnote(f"first fruiting of resprouts: {frr} after fire (grn = green fruit, imm = immature, ri = ripe, shd = shedding seed or spores)")
    if frs: addnote(f"first fruiting from seed: {frs} after fire")
    if c[2]: addnote(f"peak of post-fire flowering or fruiting printed {c[2]} (prob. = probable, poss. = possible, pk = peak, pf = post-fire, c. = approximately; subjective estimate)")
    if flr: fill(d0,data,"Time to first flower production resprout_repr3a",flr,"first flowering of resprouts",True)
    if fls: fill(d0,data,"Age at first flower production from seed_repr3",fls,"first flowering from seed",True)
    if pjp: fill(d0,data,"primary_juvenile_period",pjp,"Primary juvenile period column",True)
    if sjp: fill(d0,data,"secondary_juvenile_period",sjp,"Secondary juvenile period column",False)
    has=bool(data or d0)
    sites=[]
    if lcr: sites.append(('LCR',lcr))
    if nl: sites.append(('NL',nl))
