        if site=='LCR': d.update(LCRX); n.append("Lane Cove River (LCR) catchment, lat 33° 45' S long 151° 05' E; observations mainly Jan 1994 - Oct 1999")
        else: d["Location_name"]="Narrabeen Lagoon catchment"; n.append("Narrabeen Lagoon (NL) catchment, about 15 km NE of Lane Cove River, no coordinates given; observations Mar - Oct 1994")
